$\pi:\N_0^2\to\N_0$ é bijetiva. Para $n\in\N_0$, sua inversa é
\eqn{02}{w=\left\lfloor\frac{\sqrt{8n+1}-1}{2}\right\rfloor,\qquad v=n-T_w,\qquad u=w-v.}
Além disso, $\pi(u,v)\le(u+v+1)^2$.

Seja $\Q_H=\{r\in\Q:\heightq(r)\le H\}$. Então
\eqn{06}{|\Q_H|\le3H^2\qquad\text{para todo }H\ge1,}
e existem $H_0$ e $c_1>0$ universais tais que
\eqn{07}{|\Q_H|\ge c_1H^2\qquad\text{para todo }H\ge H_0.}
Pode-se tomar $c_1=1/4$.

Para cada $k$, as células $J_{k,m}^{\rm own}$ particionam $\R$ e
\eqn{11}{J_{k,m}=J_{k+1,2m}\cup J_{k+1,2m+1},\qquad |J_{k,m}|=2^{-k}.}
O mapa $(k,m)\mapsto x_0(k,m)$ é uma bijeção de $\N_0\times\Z$ sobre $\D_{\rm mid}$, que é denso em $\R$.

O mapa
\eqn{19}{n\longmapsto(x_{0,n},y_{0,n},s_n)}
é uma bijeção de $\N_0$ sobre $\D_{\rm mid}\times\Q\times\Q^*$. Sua imagem é densa em $\R^3$.

Se $K=[\alpha,\beta]$ é um intervalo compacto não degenerado, $\Asm(K)$ é o conjunto das funções $g\in C(K)$ para as quais existe uma coleção finita $\Lambda$ de células diádicas, com interiores disjuntos e união contendo $K$, e endereços $n(J)$, $J\in\Lambda$, tais que
\eqn{20}{g|_{J\cap K}=\ell_{n(J)}|_{J\cap K},}
com valores coincidentes nas fronteiras compartilhadas.

Seja $g\in\Asm(K)$ dada por $N$ folhas consecutivas, com nós $t_0<t_1<\cdots<t_N$ e inclinação racional não nula $s_j$ em $[t_j,t_{j+1}]\cap K$, $0\le j<N$. Então, em $K$,
\eqn{24}{g(x)=g(t_0)+s_0(x-t_0)+\sum_{j=1}^{N-1}(s_j-s_{j-1})\rho(x-t_j).}
Depois de expandido o primeiro termo afim, todos os coeficientes são racionais, todos os pontos de quebra internos são diádicos e \eqref{eq:24} é uma rede ReLU rasa normalizada com $N-1$ unidades hinge e um termo afim de saída. Unidades cujo peso de saída é zero podem ser removidas.

Reciprocamente, seja
\eqn{25}{R(x)=c+qx+\sum_{j=1}^Ma_j\rho(x-\tau_j),\qquad c,q,a_j\in\Q,\quad\tau_j\in\D,}
com nós distintos. Suponha que $K$ admita uma cobertura por células diádicas compatível com os $\tau_j$, que os valores nodais sejam racionais e que cada inclinação local
\eqn{26}{q+\sum_{\tau_j<x}a_j}
seja não nula. Então $R|_K\in\Asm(K)$. Uma malha diádica uniforme que refine todos os $\tau_j$ fornece essa montagem explicitamente.

Se $f(x_0)\in\Q$ e $f'(x_0)\in\Q^*$, então $T_{x_0}f$ é o átomo de $\LL$ associado à célula. Em geral, para todo $\delta>0$ existem $q_0\in\Q$ e $q_1\in\Q^*$ tais que $\ell_q(x)=q_0+q_1(x-x_0)$ satisfaz
\eqn{28}{
ormK{T_{x_0}f-\ell_q}{J_{k,m}}<\delta,}
\eqn{29}{
ormK{f-\ell_q}{J_{k,m}}\le rac{h^2}8
ormK{f''}{J_{k,m}}+\delta.}

Ponha $h=2^{-k}$ e $M=\normK{f''}{[\alpha,\beta]}$. Então
\eqn{31}{\normK{f-P_kF}{[\alpha,\beta]}\le\frac{h^2M}8,}
e
\eqn{32}{\lim_{k\to\infty}\frac8{h^2}\normK{f-P_kF}{[\alpha,\beta]}=M.}
Além disso, para todo $\delta>0$ existe $g_{k,\delta}\in\Asm([\alpha,\beta])$ com
\eqn{33}{\norm{f-g_{k,\delta}}\le\frac{h^2M}8+\delta.}

O algoritmo~6.3 termina e produz $g\in\Asm([\alpha,\beta])$ com
\eqn{42}{\norm{f-g}\le\varepsilon_I+\varepsilon_R.}
Se a cobertura inicial tem $R_0$ raízes de largura máxima $h_0$ e $M_*>0$, nenhuma ramificação ultrapassa
\eqn{43}{r_*=\max\left\{0,\left\lceil\frac12\log_2\left(\frac{h_0^2M_*}{8\varepsilon_I}\right)\right\rceil\right\}}
níveis, e há no máximo $R_02^{r_*}$ folhas. Se $M_*=0$, pode-se tomar $r_*=0$.

\label{prop:preliminary-facts}
As montagens são densas em $C(K)$. Se $P_Jf$ interpola $f$ nos extremos de $J$ e $f\in C^2(J)$, então
\begin{equation}
 \|f-P_Jf\|_{\infty,J}\le\frac{|J|^2}{8}\|f''\|_{\infty,J}.
 \label{eq:interpolation-remainder}
\end{equation}
Para uma montagem com nós $t_0<\cdots<t_N$ e inclinações $s_j$, vale, com $\rho(z)=\max\{0,z\}$,
\begin{equation}
 g(x)=g(t_0)+s_0(x-t_0)+\sum_{j=1}^{N-1}(s_j-s_{j-1})\rho(x-t_j).
 \label{eq:assembly-relu}
\end{equation}

\label{thm:index-bound}
O único endereço $n$ do átomo satisfaz
\begin{equation}
 n=O(H^8),\qquad \log_2(n+1)=O(\log H).
 \label{eq:index-bound}
\end{equation}
As constantes são universais para a enumeração fixada.

\label{lem:atom-count}
Para todo $H\ge2$,
\begin{equation}
 |\Library_H|\le18H^6.
 \label{eq:atom-count-upper}
\end{equation}
Além disso, existem uma constante universal $c_\Library>0$ e $H_1\ge2$ tais
que, para todo $H\ge H_1$,
\begin{equation}
 |\Library_H|\ge c_\Library H^6.
 \label{eq:atom-count}
\end{equation}
Em particular, $|\Library_H|=\Theta(H^6)$.

\label{prop:gamma-exact-order}
Se
\[
 M_\Gamma(H):=\max_{a\in\Library_H}\Gamma^{-1}(a),
\]
então
\begin{equation}
 M_\Gamma(H)=\Theta(H^8).
 \label{eq:gamma-exact-order}
\end{equation}
Consequentemente, o comprimento da maior palavra do gerador aritmético sobre
$\Library_H$ é $8\log_2H+O(1)$ bits.

\label{thm:address-lower}
Seja $A:\Library\to\Nzero$ uma aplicação injetiva qualquer. Para todo $H\ge2$,
\begin{equation}
 \max_{a\in\Library_H}A(a)\ge |\Library_H|-1.
 \label{eq:address-pigeonhole}
\end{equation}
Consequentemente, para todo $H\ge H_1$, existe um átomo de altura no máximo
$H$ com
\begin{equation}
 A(\text{átomo})\ \ge\ c_\Library H^6-1,
 \qquad\text{logo}\qquad
 \log_2\bigl(A(\text{átomo})+1\bigr)\ \ge\ 6\log_2H-O(1).
 \label{eq:address-lower}
\end{equation}
Em particular, nenhum esquema de endereçamento injetivo, canônico ou não,
pode usar $o(\log H)$ bits no pior caso sobre $\Library_H$. O expoente $6$ é
o expoente minimax para a exaustão determinada por \eqref{eq:atom-height}.

\label{thm:sharp-optimal}
A aplicação $\Gamma^\sharp$ é uma bijeção de $\Nzero$ sobre $\Library$, computável nos dois sentidos, e para todo $H\ge2$
\begin{equation}
 \max_{a\in\Library_H}n^\sharp(a)=|\Library_H|-1\ \le\ 18H^6-1 .
 \label{eq:sharp-upper}
\end{equation}
Além disso, para \emph{qualquer} endereçamento injetivo $A:\Library\to\Nzero$,
\begin{equation}
 \max_{a\in\Library_H}A(a)\ \ge\ |\Library_H|-1 .
 \label{eq:sharp-minimax}
\end{equation}
Logo $\Gamma^\sharp$ realiza, com igualdade e para todo $H$, o mínimo possível
do maior índice no pior caso sobre $\Library_H$; em particular esse pior
índice é $\Theta(H^6)$ e seu comprimento binário é minimax-ótimo para o
calibre \eqref{eq:atom-height}.

\label{lem:height-arithmetic}
Para quaisquer $r,s\in\mathbb Q$,
\begin{equation}
 \height(r\pm s)\le2\height(r)\height(s),
 \qquad
 \height(rs)\le\height(r)\height(s).
 \label{eq:height-arithmetic}
\end{equation}
Em particular, se ambos têm altura no máximo $H$, as cotas respectivas são
$2H^2$ e $H^2$.
Para uma montagem de altura atômica máxima $H$, todo nó interno
$t_j=u_j2^{-k_j}$ satisfaz $|u_j|\le H$ e $k_j\le H$ em sua forma reduzida;
além disso,
\begin{align}
 \height(s_j-s_{j-1})&\le2H^2,\label{eq:slope-jump-height}\\
 \height(s_jt_j)&\le H2^H,\label{eq:slope-knot-height}\\
 \height\bigl(g(t_0)-s_0t_0\bigr)&\le2^{H+1}H^2.
 \label{eq:intercept-height}
\end{align}

\label{thm:coding-formats}
Os três fluxos acima são prefix-free e possuem decodificadores exatos. Para
toda montagem com $N$ folhas e altura atômica máxima $H\ge2$,
\begin{equation}
 L_{\rm atom}(g)=O(N\log H),\qquad
 L_{\rm ReLU,str}(g)=O(N\log H),\qquad
 L_{\rm ReLU,rat}(g)=O(NH),
 \label{eq:coding-format-orders}
\end{equation}
com constantes universais. A última ordem é atingida conjuntamente em $N$ e
$H$: para todo $H\ge2$ e todo $N$ par com $2\le N\le H$, considere as folhas
$J_{H-1,j}$, $0\le j<N$, com valores centrais zero e inclinações $(-1)^j$.
Essa montagem contínua tem altura $H$, e
\begin{equation}
 L_{\rm atom}=O(N\log H),\qquad
 L_{\rm ReLU,str}=O(N\log H),\qquad
 L_{\rm ReLU,rat}=\Omega(NH).
 \label{eq:coding-gap-family}
\end{equation}
Assim, a equivalência funcional montagem--ReLU preserva a ordem de bits sob o
formato estrutural fixado, mas não sob a expansão racional ingênua dos
diádicos.

\label{def:joint-error}
Para inteiros $N,H\ge2$, seja $\Aclass_{N,H}(K)$ o conjunto das funções
$g\in\Aclass(K)$ que admitem uma representação como na
\cref{def:assembly} com no máximo $N$ folhas e com todos os átomos em
$\Library_H$. Defina
\begin{equation}
 E_{N,H}^{\Library}(f)_\infty
 :=\inf_{g\in\Aclass_{N,H}(K)}\|f-g\|_{\infty,K},
 \qquad \inf\varnothing:=+\infty.
 \label{eq:joint-error}
\end{equation}
Quando o conjunto abaixo não é vazio, ponha ainda
\begin{equation}
 H_{\varepsilon,N}^{\Library}(f)
 :=\min\{H\ge2:E_{N,H}^{\Library}(f)_\infty\le\varepsilon\}.
 \label{eq:height-for-accuracy}
\end{equation}

\label{lem:derivative-control}
Se $f\in\mathcal F_{R,M}$ e
\begin{equation}
 C_0:=4R+\frac M2,
 \label{eq:derivative-constant}
\end{equation}
então $\|f'\|_\infty\le C_0$.

\label{thm:joint-budget}
Defina
\begin{equation}
 C_H:=\max\{4(R+1),\ 2(C_0+1)\}.
 \label{eq:joint-height-constant}
\end{equation}
Para toda potência diádica $n=2^r\ge2$ e todo
$f\in\mathcal F_{R,M}$, existe uma montagem $g_n$ com exatamente $n$
folhas tal que
\begin{align}
 \|f-g_n\|_\infty
 &\le\frac{M+4}{8n^2},
 \label{eq:joint-dyadic-error}\\
 \height_{\max}(g_n)&\le C_Hn^2.
 \label{eq:joint-dyadic-height}
\end{align}
Nos três formatos do \cref{thm:coding-formats}, a mesma montagem satisfaz
\begin{equation}
 L_{\rm atom}(g_n),\ L_{\rm ReLU,str}(g_n),\
 L_{\rm ReLU,rat}(g_n)=O_{R,M}(n\log(2n)).
 \label{eq:joint-dyadic-bits}
\end{equation}
Consequentemente, para todo inteiro $N\ge2$,
\begin{equation}
 E_{N,\lceil C_HN^2\rceil}^{\Library}(f)_\infty
 <\frac{M+4}{2N^2}.
 \label{eq:joint-all-N}
\end{equation}
A construção é determinística: quando $f(t_j)$ é equidistante dos dois
pontos admissíveis da grade alternada, escolhe-se o ponto menor, ou,
equivalentemente no denominador comum de \eqref{eq:joint-common-denominator},
o menor numerador $b_j$.

\label{cor:height-for-epsilon}
Para $\varepsilon>0$, seja
\begin{equation}
 n_\varepsilon
 =2^{\left\lceil\log_2\max\left\{2,
        \sqrt{\frac{M+4}{8\varepsilon}}\right\}\right\rceil},
 \qquad
 H_\varepsilon=\lceil C_Hn_\varepsilon^2\rceil.
 \label{eq:epsilon-schedule}
\end{equation}
Então, uniformemente para $f\in\mathcal F_{R,M}$,
\begin{align}
 E_{n_\varepsilon,H_\varepsilon}^{\Library}(f)_\infty
 &\le\varepsilon,\label{eq:epsilon-joint-error}\\
 n_\varepsilon&=O_{R,M}(\varepsilon^{-1/2}),
 &H_\varepsilon&=O_{R,M}(\varepsilon^{-1}),
 \label{eq:epsilon-joint-height}\\
 L_{\rm atom},\ L_{\rm ReLU,str},\ L_{\rm ReLU,rat}
 &=O_{R,M}\!\left(\varepsilon^{-1/2}
                   \log\frac{2}{\varepsilon}\right).
 \label{eq:epsilon-joint-bits}
\end{align}
Em particular,
$H_{\varepsilon,n_\varepsilon}^{\Library}(f)\le H_\varepsilon$.

\label{thm:entropy}
Existem $\varepsilon_0,c,C,C_1>0$, dependentes apenas de $R$ e $M$, tais que, para $0<\varepsilon<\varepsilon_0$,
\begin{equation}
 c\varepsilon^{-1/2}
 \le\mathcal{H}_\varepsilon(\mathcal{F}_{R,M})
 \le C\varepsilon^{-1/2}.
 \label{eq:entropy-order}
\end{equation}
Existe também um codebook finito $\mathcal{C}_\varepsilon\subset\Aclass([0,1])$, composto somente por montagens de átomos de $\Library$, com distorção no máximo $\varepsilon$. Quando o codebook e seu decodificador são informação compartilhada, o comprimento de seu índice global de comprimento fixo é
\begin{equation}
 L_\varepsilon^{\mathrm{global}}(\mathcal C_\varepsilon)
 :=\left\lceil\log_2|\mathcal{C}_\varepsilon|\right\rceil
 \le C_1\varepsilon^{-1/2}.
 \label{eq:code-length}
\end{equation}
Logo esse codebook atinge em ordem a entropia métrica da classe em cardinalidade e em bits de índice global.

\label{thm:finite-catalog-minimizer}
O catálogo $\Sigma_{D,H}^{\Library}(K)$ é finito e não vazio. Mais
precisamente, se
\[
 T_0=1,\qquad T_{d+1}=1+T_d^2,
\]
então
\begin{equation}
 1\le |\Sigma_{D,H}^{\Library}(K)|
 \le |\mathfrak R_{D,H}^{\Library}(K)|
 \le T_D|\Library_H|^{2^D}<\infty.
 \label{eq:finite-catalog-bound}
\end{equation}
Consequentemente, para qualquer funcional
$\mathcal J:\Sigma_{D,H}^{\Library}(K)\to\mathbb R$, existe
\begin{equation}
 g^\star\in\argmin_{g\in\Sigma_{D,H}^{\Library}(K)}\mathcal J(g).
 \label{eq:finite-argmin}
\end{equation}
Entre todos os minimizadores, a regra do menor fluxo shortlex seleciona uma
única função e uma única representação canônica.

\label{prop:catalog-consistency}
Se $D\le D'$ e $H\le H'$, então
\begin{equation}
 \Sigma_{D,H}^{\Library}(K)
 \subseteq\Sigma_{D',H'}^{\Library}(K).
 \label{eq:catalog-nesting}
\end{equation}
Para um funcional fixado na união dos catálogos, os valores mínimos são, por
isso, não crescentes em $D$ e $H$. Se o funcional possui um minimizador global
nessa união, o minimizador global de menor fluxo shortlex e sua representação
canônica pertencem a algum catálogo finito; a partir desse par de truncagens,
o seletor canônico estabiliza.

\label{def:admissible-pairs}
Para $H\ge2$, defina $\Pairs_H(J)$ como o conjunto dos pares
$(u,v)\in\mathbb Q^2$ que satisfazem
\begin{align}
 u&\ne v,\label{eq:pair-nonzero}\\
 \max\!\left\{\height\!\left(\frac{u+v}{2}\right),
 \height\!\left(2^k(v-u)\right)\right\}&\le H,\label{eq:pair-arithmetic}\\
 k+1&\le H,\qquad |m|+1\le H.\label{eq:pair-geometry}
\end{align}

\label{prop:endpoint-dictionary}
O mapa que associa a um átomo de $\Library_H$ com suporte $J$ seus valores
nas extremidades é uma bijeção sobre $\Pairs_H(J)$. Em particular, se
\[
 \mathcal Q_H=\{r\in\mathbb Q:\height(r)\le H\},
 \qquad q_H=|\mathcal Q_H|,
\]
então
\begin{equation}
 |\Pairs_H(J)|=
 \begin{cases}
 q_H(q_H-1),&\text{se \eqref{eq:pair-geometry} vale},\\
 0,&\text{caso contrário}.
 \end{cases}
 \label{eq:pair-count}
\end{equation}

\label{def:value-alphabet}
Defina
\begin{equation}
 \Values_{D,H}(K)
 =\bigcup_{J\in\mathcal D_D(K)}
 \{u,v:(u,v)\in\Pairs_H(J)\}.
 \label{eq:value-alphabet}
\end{equation}

\label{lem:value-alphabet}
O conjunto $\Values_{D,H}(K)$ é finito. Todo valor assumido em uma fronteira
de folha por qualquer representação de
$\Representations_{D,H}^{\Library}(K)$ pertence a
$\Values_{D,H}(K)$. Se $S_D=2^{D+1}-1$, então
\begin{equation}
 |\Values_{D,H}(K)|
 \le \min\{2S_Dq_H(q_H-1),\,2|\Library_H|\}
 \le \min\{18S_DH^4,\,36H^6\}.
 \label{eq:value-alphabet-bound}
\end{equation}

\label{prop:translation-obstruction}
Seja $K=J_{k_0,m_0}$ com $m_0\ge0$ e seja
$J=J_{k_0+r,\,2^rm_0+j}$, $0\le j<2^r$, um descendente na profundidade
relativa $r$. Então $\Pairs_H(J)\ne\varnothing$ se e somente se
\begin{equation}
 k_0+r+1\le H
 \qquad\text{e}\qquad
 2^rm_0+j+1\le H.
 \label{eq:two-obstructions}
\end{equation}
Em particular, o número $N_r$ de células não vazias na profundidade $r$ é
\begin{equation}
 N_r=
 \begin{cases}
 \min\{2^r,\ \max\{0,H-2^rm_0\}\},&k_0+r+1\le H,\\
 0,&k_0+r+1>H.
 \end{cases}
 \label{eq:nonempty-cell-count}
\end{equation}
Além disso, \emph{todas} as $2^r$ células dessa profundidade são não vazias
se e somente se
\begin{equation}
 k_0+r+1\le H
 \qquad\text{e}\qquad
 2^r(m_0+1)\le H,
 \label{eq:uniform-refinement-conditions}
\end{equation}
isto é,
\begin{equation}
 r\le
 \min\!\left\{H-k_0-1,\ \log_2\frac{H}{m_0+1}\right\}.
 \label{eq:uniform-refinement-depth}
\end{equation}

\label{lem:recursive-stream}
O conjunto dos fluxos \eqref{eq:recursive-stream} é prefix-free e cada fluxo
recupera uma única árvore rotulada. Seu comprimento $B(R)$ satisfaz
\begin{equation}
 B(a)=1+|\gamma(n^\sharp(a)+1)|,\qquad
 B(R_L\vee R_R)=1+B(R_L)+B(R_R).
 \label{eq:stream-additivity}
\end{equation}

\label{def:fixed-recurrence}
Defina $C_T(J;u,v)$ de baixo para cima. Se $J$ é folha de $T$,
\begin{equation}
 C_T(J;u,v)=\Phi_H(J;u,v).
 \label{eq:fixed-leaf}
\end{equation}
Se $J$ é interno, com filhos $J_L,J_R$, defina
\begin{equation}
 C_T(J;u,v)=\lambda_{\rm bits}+\lambda_{\rm split}
 +\min_{w\in\Values_{D,H}(K)}
 \{C_T(J_L;u,w)+C_T(J_R;w,v)\}.
 \label{eq:fixed-split}
\end{equation}
Adota-se $\min\varnothing=+\infty$ e as regras usuais para soma com
$+\infty$.

\label{thm:fixed-correctness}
Para todo nó $J$ de $T$ e todo par de estados $(u,v)$,
\begin{equation}
 C_T(J;u,v)
 =\min_{R\in\Representations_H(T_J;u,v)}
 \cost_{\mathcal Z}(R),
 \label{eq:fixed-correctness}
\end{equation}
com valor $+\infty$ se o conjunto à direita for vazio. Se, em cada mínimo,
for armazenado também o candidato de menor chave \eqref{eq:tie-key}, a
retropropagação reconstrói uma única representação canônica. Em particular,
\begin{equation}
 \min_{u,v\in\Values_{D,H}(K)}C_T(K;u,v)
 =\min_{R\in\Representations_H(T)}\cost_{\mathcal Z}(R).
 \label{eq:fixed-global}
\end{equation}

\label{def:variable-recurrence}
Para $d=0$, ponha
\begin{equation}
 C_0(J;u,v)=\Phi_H(J;u,v).
 \label{eq:variable-base}
\end{equation}
Para $d\ge1$, se $J_L,J_R$ são os filhos de $J$, defina
\begin{align}
 C_d(J;u,v)
 =\min\Bigl\{&
 \Phi_H(J;u,v),\notag\\
 &\lambda_{\rm bits}+\lambda_{\rm split}
 +\min_{w\in\Values_{D,H}(K)}
 \bigl[C_{d-1}(J_L;u,w)+C_{d-1}(J_R;w,v)\bigr]
 \Bigr\}.
 \label{eq:variable-recurrence}
\end{align}

\label{thm:variable-correctness}
Seja $J$ uma célula descendente de $K$ na profundidade relativa $r$. Para todo
$d\le D-r$ e todo $(u,v)\in\Values_{D,H}(K)^2$,
\begin{equation}
 C_d(J;u,v)
 =\min_{R\in\Representations_{d,H}(J;u,v)}
 \cost_{\mathcal Z}(R).
 \label{eq:variable-correctness}
\end{equation}
Consequentemente,
\begin{equation}
 C_{D,H}^{\star}(K)
 :=\min_{u,v\in\Values_{D,H}(K)}C_D(K;u,v)
 =\min_{R\in\Representations_{D,H}^{\Library}(K)}
 \cost_{\mathcal Z}(R).
 \label{eq:variable-global}
\end{equation}
O mínimo é finito quando
$H\ge\max\{2,k_0+1,|m_0|+1\}$. Com o desempate
\eqref{eq:tie-key}, o algoritmo devolve uma única representação, independentemente
da ordem em que estados, átomos ou valores intermediários sejam gerados.

\label{cor:shape-enumeration}
Se $\Trees_D(K)$ é o conjunto finito de todas as formas de árvore de
profundidade no máximo $D$, então
\begin{equation}
 C_{D,H}^{\star}(K)
 =\min_{T\in\Trees_D(K)}
   \min_{u,v\in\Values_{D,H}(K)}C_T(K;u,v).
 \label{eq:shape-equivalence}
\end{equation}
O mesmo fluxo canônico vence nos dois lados.

\label{thm:leaf-budget}
As recorrências \eqref{eq:budget-base}--\eqref{eq:budget-recurrence}
calculam exatamente o menor custo entre representações de profundidade no
máximo $d$, altura no máximo $H$, fronteiras $(u,v)$ e exatamente $n$
folhas. Em particular, o ótimo com no máximo $N$ folhas é
\begin{equation}
 \min_{\substack{1\le n\le\min\{N,2^D\}\\
                  u,v\in\Values_{D,H}(K)}}
 C_{D,n}(K;u,v).
 \label{eq:at-most-N}
\end{equation}

\label{thm:bottleneck}
Sob o oráculo \eqref{eq:local-uniform-error},
\begin{equation}
 E_{N,H,D}^{\rm tree}(f)_\infty
 =\min_{\substack{1\le n\le\min\{N,2^D\}\\
                  u,v\in\Values_{D,H}(K)}}
 B_{D,n}(K;u,v).
 \label{eq:bottleneck-optimum}
\end{equation}
Se
\begin{equation}
 D\ge \max\{0,H-k_0-1\},
 \label{eq:depth-inactive}
\end{equation}
a restrição de profundidade já é inativa: nenhum átomo de $\Library_H$
apoiado em descendente de $K$ pode ocorrer abaixo desse nível.

\label{cor:uniform-convergence}
Para todo $f\in C(K)$,
\begin{equation}
 \inf_{N,H,D}E_{N,H,D}^{\rm tree}(f)_\infty=0.
 \label{eq:uniform-convergence}
\end{equation}
Mais precisamente, ao longo de qualquer sequência de triplas $(N,H,D)$ que
seja componente a componente não decrescente e cofinal, os erros convergem a
zero.

\label{thm:state-complexity}
Suponha os custos de folha pré-computados. Uma implementação densa do
\cref{alg:variable-tree} usa
\begin{equation}
 O(S_DM^3)
 \label{eq:dense-time}
\end{equation}
operações e
\begin{equation}
 O(S_DM^2)
 \label{eq:dense-memory}
\end{equation}
entradas de memória quando preserva todos os apontadores de reconstrução.
A versão com orçamento de até $N$ folhas usa
\begin{equation}
 O(S_DN^2M^3)
 \label{eq:budget-time}
\end{equation}
operações e $O(S_DNM^2)$ entradas. Se cada custo local
\eqref{eq:local-loss} for calculado diretamente sobre $P$ observações, a
inicialização densa acrescenta $O(S_DPM^2)$ operações.

\label{thm:bit-complexity}
Todos os custos racionais que aparecem na recorrência possuem numeradores e
denominadores de comprimento no máximo
\begin{equation}
 B_{\rm cost}
 =O\!\left(
 P\bigl(B_{\mathcal Z}+D+|k_0|+\log(2H)\bigr)
 +B_{\mathcal Z}+D+\log(2L)
 \right).
 \label{eq:cost-bit-growth}
\end{equation}
Consequentemente, a versão densa sem orçamento de folhas pode ser executada em
\begin{equation}
 O\!\left(
 (S_DM^3+S_DPM^2)
 \bigl[\mathsf M_{\mathbb Z}(B_{\rm cost})
       \log(2B_{\rm cost})+L\bigr]
 \right)
 \label{eq:dense-bit-time}
\end{equation}
operações de bit e
\begin{equation}
 O\!\left(S_DM^2(B_{\rm cost}+L)\right)
 \label{eq:dense-bit-memory}
\end{equation}
bits de memória quando todos os estados e fluxos são armazenados. Na versão
com até $N$ folhas, substituem-se $S_DM^3$ e $S_DM^2$ por
$S_DN^2M^3$ e $S_DNM^2$, respectivamente. Com multiplicação escolar,
$\mathsf M_{\mathbb Z}(b)=O(b^2)$.

\label{prop:truncation-convergence}
Os valores $C_{D,H}^{\star}(K)$ de \eqref{eq:variable-global} são não
crescentes separadamente em $D$ e $H$, e
\begin{equation}
 \inf_{D,H}C_{D,H}^{\star}(K)
 =\inf_{R\in\Representations_{\infty}^{\Library}(K)}
   \cost_{\mathcal Z}(R).
 \label{eq:penalized-limit}
\end{equation}
Ao longo de qualquer sequência componente a componente não decrescente e
cofinal em $(D,H)$, os valores convergem ao lado direito.

Se o ínfimo em \eqref{eq:penalized-limit} é atingido, o minimizador global de
menor chave \eqref{eq:tie-key} pertence a algum catálogo finito; a partir de
uma truncagem que o contenha, o seletor canônico estabiliza.

\label{thm:threshold-optimality}
Se $f\in C(K)$, então $T_\varepsilon(f)$ é finita e é a única árvore
menos refinada (\emph{coarsest}) cuja interpolação tem erro no máximo $\varepsilon$. Em particular,
ela possui o menor número de folhas entre todas as árvores viáveis e
\begin{equation}
 E_N^{\rm dia}(f)_\infty\le\varepsilon
 \quad\Longleftrightarrow\quad
 n_f(\varepsilon)\le N,
 \qquad
 E_N^{\rm dia}(f)_\infty
 =\inf\{\varepsilon>0:n_f(\varepsilon)\le N\}.
 \label{eq:threshold-inversion}
\end{equation}

\label{lem:local-asymptotic-error}
Para toda célula $J\subseteq K$ e todo $x\in J$,
\begin{equation}
 \left|e_f(J)-\frac{|f''(x)|}{8}|J|^2\right|
 \le \frac{\omega_{f''}(|J|)}{8}|J|^2.
 \label{eq:local-asymptotic-error}
\end{equation}

\label{thm:general-dyadic-envelope}
Se $f\in C^2(K)$ e $I(f)>0$, então
\begin{align}
 \frac{I(f)}{\sqrt8}
 &\le \liminf_{\varepsilon\downarrow0}
       \sqrt\varepsilon\,n_f(\varepsilon)
 \le \limsup_{\varepsilon\downarrow0}
       \sqrt\varepsilon\,n_f(\varepsilon)
 \le \frac{I(f)}{\sqrt2},
 \label{eq:threshold-envelope}\\
 \frac{I(f)^2}{8}
 &\le \liminf_{N\to\infty}N^2E_N^{\rm dia}(f)_\infty
 \le \limsup_{N\to\infty}N^2E_N^{\rm dia}(f)_\infty
 \le \frac{I(f)^2}{2}.
 \label{eq:budget-envelope}
\end{align}
As afirmações continuam válidas se $f''$ possui zeros ou muda de sinal. Se
$I(f)=0$, então $f$ é afim e ambos os erros são identicamente zero.

\label{thm:quadratic-dyadic-constant}
Se $K$ é uma célula diádica de comprimento $L$ e
$q''\equiv\kappa\ne0$ em $K$, ponha
\begin{equation}
 A=\frac{|\kappa|L^2}{8}.
 \label{eq:quadratic-A}
\end{equation}
Então, para todo $N\ge1$,
\begin{equation}
 E_N^{\rm dia}(q)_\infty
 =A\,4^{-\lfloor\log_2N\rfloor}.
 \label{eq:quadratic-exact-law}
\end{equation}
Consequentemente,
\begin{equation}
 \liminf_{N\to\infty}N^2E_N^{\rm dia}(q)_\infty=A,
 \qquad
 \limsup_{N\to\infty}N^2E_N^{\rm dia}(q)_\infty=4A,
 \label{eq:quadratic-liminf-limsup}
\end{equation}
e o conjunto completo dos valores de acumulação de
$N^2E_N^{\rm dia}(q)_\infty$ é o intervalo $[A,4A]$. Em particular, a
constante obtida por um limite simples não existe.

\label{cor:synchronized-phases}
Nas hipóteses do \cref{thm:piecewise-quadratic-count}, suponha ainda que
$A_i/A_j\in4^{\mathbb Z}$ para todos $i,j$. Então
\begin{equation}
 \liminf_{N\to\infty}N^2E_N^{\rm dia}(f)_\infty=\frac{I(f)^2}{8},
 \qquad
 \limsup_{N\to\infty}N^2E_N^{\rm dia}(f)_\infty=\frac{I(f)^2}{2}.
 \label{eq:synchronized-extremes}
\end{equation}

\label{prop:schedule-nesting}
Se $H$ é não decrescente, então
\begin{equation}
 \Sigma_N^{\Library,H}(K)
 \subseteq\Sigma_{N+1}^{\Library,H}(K)
 \quad\text{e}\quad
 e_{N+1}^{\Library,H}(f)\le e_N^{\Library,H}(f)\le\|f\|_\infty.
 \label{eq:schedule-nesting}
\end{equation}
Para cada $N$, o ínfimo em \eqref{eq:pointed-error} é atingido.

\label{thm:dyadic-rate-equivalence}
Para toda agenda não decrescente, $\alpha>0$ e $0<q\le\infty$,
\begin{equation}
 \mathfrak a_{\alpha,q}^{\Library,H}(f)
 \asymp_{\alpha,q}
 \left\|\bigl(2^{r\alpha}
 e_{2^r}^{\Library,H}(f)\bigr)_{r\ge0}\right\|_{\ell^q},
 \label{eq:dyadic-rate-equivalence}
\end{equation}
com a interpretação usual por supremo quando $q=\infty$. As constantes não
dependem de $f$ nem de $H$.

\label{prop:nonhomogeneous-functional}
Suponha $K=[0,1]$ e $H(1)\ge2$. O funcional
$\|f\|_\infty+\mathfrak a_{\alpha,q}^{\Library,H}(f)$ não é homogêneo sobre
$C(K)$ e, portanto, não é uma quase-norma. Mais precisamente, para
$f(x)=x$ e $c=\sqrt2$,
\begin{equation}
 \mathfrak a_{\alpha,q}^{\Library,H}(f)=0,
 \qquad
 \mathfrak a_{\alpha,q}^{\Library,H}(cf)>0.
 \label{eq:nonhomogeneous-certificate}
\end{equation}

\label{lem:rational-jackson-height}
Seja $f\in B^s_{\infty,\infty}(K)$, $R=\|f\|_\infty$. Existe
$n_0=n_0(f,K,s)$ tal que, para toda potência de dois $n=2^r\ge n_0$ e todo
inteiro
\[
 H\ge\max\{C_Kn^{\nu_s},16(R+1)\}
\]
que satisfaça
\begin{equation}
 H\ge\max\{2,k_0+r+1,
      \max_{0\le j<n}|2^rm_0+j|+1\},
 \label{eq:height-geometry-condition}
\end{equation}
existe $g_{n,H}\in\Aclass_{n,H}(K)$ tal que
\begin{equation}
 \|f-g_{n,H}\|_\infty
 \le 2C_W\omega_2(f,L/n)_{\infty,K}
      +\frac{C(R+1)}{H},
 \label{eq:rational-jackson-height}
\end{equation}
onde $C$ é absoluto e $C_W$ é a constante de Whitney.

Além disso, existe $A_{K,s}\ge1$, independente de $f$, com a seguinte versão
uniforme. Se $B\ge1$, $\|f\|_{B^s_{\infty,\infty}(K)}^*\le B$, $n=2^r\ge2$
e
\begin{equation}
 H\ge A_{K,s}(B+1)n^{\nu_s},
 \label{eq:uniform-ball-height-threshold}
\end{equation}
então todas as conclusões anteriores valem sem limiar dependente de $f$ e com
o último termo de \eqref{eq:rational-jackson-height} igual a
$8(B+1)/H$. A constante $A_{K,s}$ também torna automática a condição
geométrica \eqref{eq:height-geometry-condition}.

\label{cor:uniform-besov-ball-embedding}
Para $B\ge1$ e $\kappa\ge0$, defina
\begin{equation}
 \widehat H_{s,\kappa}^{[B]}(N)
 =\left\lceil A_{K,s}(B+1)(N+1)^{\nu_s}
        [\log(eN)]^\kappa\right\rceil .
 \label{eq:ball-calibrated-height-schedule}
\end{equation}
Existem constantes independentes de $B$ e de $f$ tais que
\begin{align}
 \sup_{\|f\|_{B^s_{\infty,\infty}(K)}^*\le B}
 \mathfrak a_{s,\infty}^{\Library,
       \widehat H_{s,0}^{[B]}}(f)
 &\le C_{K,s}(B+1), &&0<s<2,\label{eq:uniform-ball-endpoint}\\
 \sup_{\|f\|_{B^s_{\infty,q}(K)}^*\le B}
 \mathfrak a_{s,q}^{\Library,
       \widehat H_{s,0}^{[B]}}(f)
 &\le C_{K,s,q}(B+1), &&0<s<1,\quad0<q<\infty,
 \label{eq:uniform-ball-subcritical}\\
 \sup_{\|f\|_{B^s_{\infty,q}(K)}^*\le B}
 \mathfrak a_{s,q}^{\Library,
       \widehat H_{s,\kappa}^{[B]}}(f)
 &\le C_{K,s,q,\kappa}(B+1),
 &&1\le s<2,\quad0<q<\infty,\quad\kappa>1/q.
 \label{eq:uniform-ball-critical}
\end{align}
Assim, cada bola de Besov é enviada uniformemente a uma bola do funcional de
taxa sob uma única agenda, sem qualquer limiar dependente da função.

\label{prop:arithmetic-floor}
Para cada $H\ge2$, seja $a_H=1/(2H)$ e $f_H\equiv a_H$ em $K$. Então, para
todo $N$,
\begin{equation}
 e_N^{\Library,H}(f_H)
 \ge\operatorname{dist}(a_H,\mathcal Q_H)
 =\frac1{2H}.
 \label{eq:arithmetic-floor}
\end{equation}
Consequentemente, se uma classe contém todas as constantes
$f\equiv a$, $|a|\le1/4$, e satisfaz
$\sup_f e_N^{\Library,H}(f)\le C N^{-s}$, então
$H(N)\ge(2C)^{-1}N^s$ para todo $N$ com $H(N)\ge2$.

\label{def:marked-completion}
A biblioteca $\Library^\square$ é formada pelas quádruplas marcadas
\begin{equation}
 (k,m,y_0,s)\in\Nzero\times\mathbb Z\times\mathbb Q\times\mathbb Q,
 \label{eq:marked-atoms}
\end{equation}
com o mesmo segmento \eqref{eq:inherited-atom} e a mesma altura
\eqref{eq:inherited-height}. A marca $(k,m)$ é conservada na decodificação,
inclusive quando $s=0$. Denote por $\Aclass^\square(K)$ suas montagens
contínuas e por $\Aclass^\square_{N,H}(K)$ aquelas com no máximo $N$
folhas e altura atômica no máximo $H$.

\label{thm:exact-marked-reversal}
Uma função na forma reduzida \eqref{eq:reduced-relu-reverse} pertence a
$\Aclass^\square([0,1])$ se e somente se
\begin{equation}
 c,q,a_1,\ldots,a_M\in\mathbb Q,
 \qquad
 \tau_1,\ldots,\tau_M\in\mathbb D.
 \label{eq:marked-reversal-conditions}
\end{equation}
Nessas condições, $\mathcal T(\{\tau_1,\ldots,\tau_M\})$ é a única árvore
menos refinada que realiza $R$. Se $N_{\rm can}(R)$ é seu número de folhas e
$d_j$ é a profundidade diádica reduzida de $\tau_j$, então
\begin{equation}
 M+1\le N_{\rm can}(R)
 \le 1+\sum_{j=1}^{M}d_j.
 \label{eq:canonical-tree-leaf-bounds}
\end{equation}
A função pertence à biblioteca original $\Aclass([0,1])$ exatamente quando,
além de \eqref{eq:marked-reversal-conditions},
\begin{equation}
 \sigma_i\ne0\qquad(0\le i\le M).
 \label{eq:original-nonflat-condition}
\end{equation}

\label{def:canonical-network-height}
Para uma rede que satisfaz \eqref{eq:marked-reversal-conditions}, defina
\begin{equation}
 H_{\rm can}(R)=
 \max_{J_{k,m}\in\operatorname{leaf}(\mathcal T(S))}
 \max\{2,k+1,|m|+1,\height(R(x_{k,m})),\height(R'|_{J_{k,m}})\}.
 \label{eq:canonical-network-height}
\end{equation}

\label{prop:anchored-relu-code}
Se $g\in\Aclass^\square_{N,H}([0,1])$, sua forma reduzida possui
$M\le N-1$ hinges e pode ser escrita, tomando o centro $x_*$ da folha mais à
esquerda, como
\begin{equation}
 g(x)=g(x_*)+\sigma_0(x-x_*)
      +\sum_{j=1}^{M}(\sigma_j-\sigma_{j-1})\rho(x-\tau_j).
 \label{eq:anchored-relu-form}
\end{equation}
Os valores $g(x_*)$ e $\sigma_i$ têm altura no máximo $H$, os saltos têm
altura no máximo $2H^2$, e os pontos diádicos são transmitidos por seus pares
estruturais. Consequentemente, existe uma codificação prefix-free da forma
ancorada com
\begin{equation}
 L_{\rm ReLU}^{\rm anc}(g)=O(N\log(2H)).
 \label{eq:anchored-network-bits}
\end{equation}

Na direção contrária, se os coeficientes de
\eqref{eq:reduced-relu-reverse} têm altura no máximo $W$ e as quebras têm
profundidade no máximo $D$, então
\begin{equation}
 \log_2 H_{\rm can}(R)
 \le C\bigl[M\log(2W)+D+\log(M+1)\bigr]
 \label{eq:reverse-height-bit-bound}
\end{equation}
para uma constante universal $C$.

\label{cor:deep-functional-reverse}
Se uma rede ReLU univariada arbitrária realiza uma função $F$ com $R(F)$
regiões afins máximas, norma uniforme no máximo $B$ e constante de Lipschitz
no máximo $L_F$, então o \cref{thm:quantized-approximate-reverse} vale com
\begin{equation}
 M=R(F)-1,
 \qquad
 W\le2\max\{1,B,L_F\}.
 \label{eq:deep-realized-resources}
\end{equation}

\label{thm:raw-lossy-inverse}
Sejam $\mathcal G_N\subset C([0,1])$ famílias de aproximantes tais que
\begin{equation}
 \operatorname{Lip}(g)\le C_LN^\gamma
 \qquad(g\in\mathcal G_N),
 \qquad \gamma\ge0,
 \label{eq:lipschitz-growth-family}
\end{equation}
e defina
$e_N^{\mathcal G}(f)=\inf_{g\in\mathcal G_N}\|f-g\|_\infty$. Se
\begin{equation}
 A_\alpha(f):=\sup_{N\ge1}N^\alpha e_N^{\mathcal G}(f)<\infty,
 \qquad \alpha>0,
 \label{eq:raw-rate-assumption}
\end{equation}
então, com
\begin{equation}
 \theta_* = \frac{\alpha}{\alpha+\gamma},
 \label{eq:critical-reverse-exponent}
\end{equation}
vale
\begin{equation}
 \omega_2(f,t)_\infty
 \le C_{\alpha,\gamma}(A_\alpha(f)+C_L)t^{\theta_*},
 \qquad 0<t\le\frac12.
 \label{eq:raw-inverse-modulus}
\end{equation}
Consequentemente,
\begin{equation}
 f\in B^{\theta_*}_{\infty,\infty}([0,1])
 \quad\text{e}\quad
 f\in B^\theta_{\infty,r}([0,1])
 \quad(0<\theta<\theta_*,\ 0<r\le\infty).
 \label{eq:raw-inverse-besov}
\end{equation}

\label{cor:raw-library-inverse}
Se $H(N)\le C N^\gamma$, então
\begin{equation}
 \mathscr A_q^\alpha(\Library,H)
 \subset B^{\alpha/(\alpha+\gamma)}_{\infty,\infty}([0,1]),
 \qquad 0<q\le\infty.
 \label{eq:raw-library-inverse}
\end{equation}
Para as agendas $H_{s,0}$ da \cref{sec:direct-height}, isso dá
\begin{equation}
 \mathscr A_q^s(\Library,H_{s,0})
 \subset B^{\vartheta_s}_{\infty,\infty},
 \qquad
 \vartheta_s=
 \begin{cases}
 s/(s+1),&0<s<1,\\
 1/2,&1\le s<2.
 \end{cases}
 \label{eq:corrected-schedule-raw-inverse}
\end{equation}
Se a agenda possui ainda um fator logarítmico, a mesma conclusão vale para
toda ordem estritamente menor que $\vartheta_s$.

\label{thm:critical-tent-comb}
Fixe $0<\alpha\le\gamma$ e ponha
$\theta_*=\alpha/(\alpha+\gamma)$. Existe
$f\in C([0,1])$ e uma constante $C$ tais que, para a biblioteca original sob
$H(N)=\lceil CN^\gamma\rceil$,
\begin{equation}
 e_N^{\Library,H}(f)\le CN^{-\alpha},
 \label{eq:comb-approximation-rate}
\end{equation}
mas
\begin{equation}
 f\notin B^\theta_{\infty,\infty}\quad(\theta>\theta_*),
 \qquad
 f\notin B^{\theta_*}_{\infty,r}\quad(0<r<\infty).
 \label{eq:comb-sharpness}
\end{equation}

\label{lem:universal-regularized-inverse}
Para toda agenda, toda $f\in C([0,1])$ e todo $N\ge2$,
\begin{equation}
 \frac14\omega_2(f,N^{-1})_\infty
 \le \mathcal R_N^{\Library,H}(f).
 \label{eq:universal-regularized-lower}
\end{equation}

\label{thm:architecture-stable-reversibility}
Seja $(\mathcal N_N)$ qualquer família de funções realizadas por redes ReLU
aninhada no orçamento, isto é,
\begin{equation}
 0\in\mathcal N_N,
 \qquad \mathcal N_N\subseteq\mathcal N_{N+1}
 \qquad(N\ge1),
 \label{eq:network-family-nesting}
\end{equation}
e suponha que, para alguma constante $c\ge1$,
\begin{equation}
 \Sigma_N^{\Library,H}([0,1])\subseteq\mathcal N_{\lceil cN\rceil}
 \qquad(N\ge1).
 \label{eq:network-family-contains-library}
\end{equation}
Defina
\begin{equation}
 \mathcal R_N^{\mathcal N}(f)
 =\inf_{R\in\mathcal N_N}
 \left\{\|f-R\|_\infty+\omega_2(R,N^{-1})_\infty\right\}.
 \label{eq:network-regularized-certificate}
\end{equation}
Sob cada uma das agendas do
\cref{thm:complete-besov-reversibility}, substituir
$\mathcal R_N^{\Library,H}$ por $\mathcal R_N^{\mathcal N}$ preserva as
igualdades \eqref{eq:complete-reverse-endpoint}--
\eqref{eq:complete-reverse-critical}.

\label{thm:norm}
Se $\Loc_K(g,\Lambda)$, então, para $\Lambda'=\Norm_K(\Lambda)$,
\begin{enumerate}
\item $\Lambda'\subseteq\Lambda$ e $|\Lambda'|\le|\Lambda|$;
\item $\Cov(K,\Lambda')$ e $\Lambda'\ne\varnothing$;
\item $J_a\cap J_b\subseteq K^\circ$ para $a\ne b$ em $\Lambda'$;
\item $\Str_K(g,\Lambda')$;
\item $\Norm_K(\Lambda')=\Lambda'$.
\end{enumerate}
As mesmas conclusões, com os predicados globais, valem sob
$\Loc^G_K(G,\Lambda)$; nesse caso a função $G$ inteira é preservada.

\label{thm:bridge}
Como subconjuntos de $\CK$,
\begin{align*}
 \mathcal B_2(K)&=\Aloc(K)=\Astr(K),\\
 \ImageRes_K(\mathcal B_3(K))&=\Aloc(K),\\
 \ImageRes_K(\mathcal B_{\rm con}(K))&=\Astr(K).
\end{align*}
Como subconjuntos de $\R\to\R$,
$\mathcal B_3(K)=\mathcal B_{\rm con}(K)$.

\label{thm:budget}
Para todos $N,H:\N$ com $H\ge2$,
$\Aloc_{N,H}(K)=\Astr_{N,H}(K)$.

\label{def:chain}
Para $\Lambda:\FS(\Atoms)$, uma estrutura
$\operatorname{NormChain}_K(\Lambda)$ contém os dados
\[
 M:\N,\quad h_M:1\le M,\quad
 a:\Fin(M)\to\Atoms,\quad t:\Fin(M+1)\to\Q
\]
e as seguintes propriedades:
\begin{enumerate}
\item $a$ é injetiva e
$\operatorname{image}(a,\operatorname{univ}_M)=\Norm_K(\Lambda)$;
\item $t_j<t_{j+1}$ para $0\le j<M$;
\item $L_\Q(C(a_j))=t_j$ e $R_\Q(C(a_j))=t_{j+1}$ para $j<M$;
\item $\uparrow t_0\le\alpha$ e $\beta\le\uparrow t_M$;
\item $\alpha<\uparrow t_j<\beta$ para $1\le j<M$.
\end{enumerate}
Na segunda e terceira cláusulas, o índice $j$ de $t$ é a inclusão
$\langle j,h_j\rangle\mapsto\langle j,h_j':j<M+1\rangle$;
o índice seguinte é $\langle j+1,j+1<M+1\rangle$.
Por definição dos extremos, a terceira cláusula implica
$J_{a_j}=[\uparrow t_j,\uparrow t_{j+1}]$, com ambos os extremos incluídos.

\label{thm:chain}
De $\Loc_K(g,\Lambda)$ obtemos uma estrutura
$\operatorname{NormChain}_K(\Lambda)$ pela seguinte construção:
\begin{align*}
 F&:=\Norm_K(\Lambda),& M&:=|F|,\\
 a_j&:=(\operatorname{sort}(F))_j\quad(j<M),\\
 t_0&:=L_\Q(C(a_0)),&
 t_{j+1}&:=R_\Q(C(a_j))\quad(j<M).
\end{align*}
Não há escolhas de enumeração adicionais nessa construção.

\label{lem:two_points}
Se duas funções afins coincidem em dois pontos distintos, coincidem
em toda a reta.

\label{thm:tree-rate}
Se $f\in C^2(K)$, $L=|K|$, $M=\|f''\|_{\infty,K}$ e $N\ge2$, então
\begin{equation}
 \sigma_N^{\mathrm{dia}}(f)_\infty\le\frac{ML^2}{2N^2}.
 \label{eq:tree-general}
\end{equation}
Se $N=2^r$, a constante melhora para
\begin{equation}
 \sigma_N^{\mathrm{dia}}(f)_\infty\le\frac{ML^2}{8N^2}.
 \label{eq:tree-power}
\end{equation}
Para qualquer árvore finita $\Lambda$ e $\delta>0$, há uma montagem racional na mesma árvore cujo erro é menor que $\|f-P_\Lambda f\|_\infty+\delta$.

\label{thm:free-knots}
Para $f\in C^2[\alpha,\beta]$,
\begin{equation}
 \limsup_{N\to\infty}N^2E_N^{\mathrm{lv}}(f)
 \le\frac18\left(\int_\alpha^\beta |f''(x)|^{1/2}\dd x\right)^2.
 \label{eq:free-knot}
\end{equation}

\label{thm:besov}
Se $0<s<2$, $|K|=L$ e o seminorma em \eqref{eq:besov-seminorm} é finito, então, para $N\ge2$,
\begin{equation}
 \sigma_N^{\mathrm{dia}}(f)_\infty
 \le C_sL^s|f|_{B^s_{\infty,\infty}(K)}N^{-s},
 \label{eq:besov-rate}
\end{equation}
onde $C_s$ independe de $f$ e $N$. Para todo $\delta>0$, uma montagem racional com no máximo $N$ folhas alcança o lado direito de \eqref{eq:besov-rate} acrescido de $\delta$.
